{"sql":"DROP TABLE IF EXISTS public.available_films; CREATE TABLE public.available_films (
  film_id INTEGER PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  rental_rate NUMERIC(4,2) NOT NULL,
  length SMALLINT
);"}

{"sql":"DELETE FROM public.inventory i
WHERE EXISTS (
  SELECT 1 FROM public.film f
  LEFT JOIN public.rental r ON r.inventory_id = i.inventory_id
  WHERE i.film_id = f.film_id
    AND f.replacement_cost > 25.00
    AND f.rental_rate < 1.00
    AND r.rental_id IS NULL
);
"}
